import{_ as o,o as a,c as t,ae as s}from"./chunks/framework.Dn6zxbF8.js";const g=JSON.parse('{"title":"Google Cloud: exposure and health checks","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1008684393/references/gcp.md","filePath":"adrs/1008684393/references/gcp.md"}'),r={name:"adrs/1008684393/references/gcp.md"};function n(c,e,i,l,d,h){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="google-cloud-exposure-and-health-checks" tabindex="-1">Google Cloud: exposure and health checks <a class="header-anchor" href="#google-cloud-exposure-and-health-checks" aria-label="Permalink to &quot;Google Cloud: exposure and health checks&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-11.</p><h2 id="exposure" tabindex="-1">Exposure <a class="header-anchor" href="#exposure" aria-label="Permalink to &quot;Exposure&quot;">​</a></h2><p>Load balancers are <strong>external</strong> or <strong>internal</strong>, defined by where the client is: an external load balancer is for clients that &quot;need to reach your application from the internet&quot;, an internal one for clients &quot;inside of Google Cloud&quot;. Scope (global, regional, cross-region) and layer (Application or Network) are separate axes, so product names combine all three, such as &quot;regional internal Application Load Balancer&quot; (<a href="https://docs.cloud.google.com/load-balancing/docs/load-balancing-overview" target="_blank" rel="noreferrer">Cloud Load Balancing overview</a>).</p><p>Addresses follow the same words. An <strong>internal IP</strong> &quot;cannot be reached from the internet&quot;; an <strong>external IP</strong> is &quot;reachable by any host on the internet&quot; (<a href="https://docs.cloud.google.com/vpc/docs/ip-addresses" target="_blank" rel="noreferrer">IP addresses</a>). &quot;Private&quot; names connectivity products instead: Private Google Access, Private Service Connect and private services access (<a href="https://docs.cloud.google.com/vpc/docs/private-access-options" target="_blank" rel="noreferrer">Private access options</a>).</p><p>Cloud Run ingress takes <code>all</code>, <code>internal</code> or <code>internal-and-cloud-load-balancing</code>. The last one admits internet traffic only through the external Application Load Balancer, so Cloud Armor, IAP and CDN apply to every public request (<a href="https://docs.cloud.google.com/run/docs/securing/ingress" target="_blank" rel="noreferrer">Restrict network ingress for Cloud Run</a>).</p><p>On GKE, a <code>LoadBalancer</code> Service becomes internal with the annotation <code>networking.gke.io/load-balancer-type: &quot;Internal&quot;</code> (<a href="https://docs.cloud.google.com/kubernetes-engine/docs/concepts/service-load-balancer" target="_blank" rel="noreferrer">About LoadBalancer Services</a>). Gateway classes carry the same vocabulary: <code>gke-l7-global-external-managed</code>, <code>gke-l7-regional-external-managed</code>, <code>gke-l7-rilb</code> and <code>gke-l7-cross-regional-internal-managed-mc</code> (<a href="https://docs.cloud.google.com/kubernetes-engine/docs/concepts/gateway-api" target="_blank" rel="noreferrer">About Gateway API</a>). The control plane is the exception: it has a <strong>private endpoint</strong> and an optional <strong>public endpoint</strong>, which Google advises enabling &quot;only if you require external administrative access&quot; (<a href="https://docs.cloud.google.com/kubernetes-engine/docs/how-to/legacy/network-isolation" target="_blank" rel="noreferrer">Private cluster concepts</a>).</p><h2 id="one-endpoint-for-grpc-and-rest" tabindex="-1">One endpoint for gRPC and REST <a class="header-anchor" href="#one-endpoint-for-grpc-and-rest" aria-label="Permalink to &quot;One endpoint for gRPC and REST&quot;">​</a></h2><p>Google&#39;s own APIs serve gRPC and REST/JSON on the same host and port, told apart by path. An API service endpoint is &quot;a network address that an API service uses to handle incoming API requests&quot;, such as <code>https://pubsub.googleapis.com</code> (<a href="https://docs.cloud.google.com/apis/design/glossary" target="_blank" rel="noreferrer">API design glossary</a>). Each method is defined once as an RPC, and an HTTP binding on it also presents that method as a REST/JSON resource path (<a href="https://google.aip.dev/127" target="_blank" rel="noreferrer">AIP-127: HTTP and gRPC Transcoding</a>). The URLs differ, the endpoint does not:</p><table tabindex="0"><thead><tr><th>Call</th><th>Path on <code>pubsub.googleapis.com:443</code></th><th>Answers with</th></tr></thead><tbody><tr><td>gRPC <code>ListTopics</code></td><td><code>POST /google.pubsub.v1.Publisher/ListTopics</code></td><td><code>application/grpc</code>, <code>grpc-status</code></td></tr><tr><td>REST <code>projects.topics</code></td><td><code>GET /v1/projects/{project}/topics</code></td><td><code>application/json</code></td></tr></tbody></table><p>Observed on 2026-10-12 with unauthenticated requests: the gRPC path answered <code>content-type: application/grpc</code> with a <code>grpc-status</code> trailer, and the REST path answered <code>content-type: application/json</code>, both over HTTP/2 on port 443:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --http2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;content-type: application/grpc&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;te: trailers&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://pubsub.googleapis.com/google.pubsub.v1.Publisher/ListTopics</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pubsub.googleapis.com/v1/projects/x/topics</span></span></code></pre></div><h2 id="one-port-for-grpc-and-http" tabindex="-1">One port for gRPC and HTTP <a class="header-anchor" href="#one-port-for-grpc-and-http" aria-label="Permalink to &quot;One port for gRPC and HTTP&quot;">​</a></h2><p>Application Load Balancers talk to backends over <code>HTTP</code>, <code>HTTPS</code>, <code>HTTP2</code> or <code>H2C</code>. <code>HTTP2</code> &quot;uses HTTP/2 and TLS (HTTP/2 without encryption isn&#39;t supported.)&quot;, while <code>H2C</code> &quot;uses HTTP/2 over TCP. TLS isn&#39;t required. H2C isn&#39;t supported for classic Application Load Balancers&quot;. The load balancer &quot;doesn&#39;t fall back to a different protocol&quot; when the backend does not speak the one configured. The gRPC backend protocol exists only for Cloud Service Mesh (<a href="https://docs.cloud.google.com/load-balancing/docs/backend-service" target="_blank" rel="noreferrer">Backend services overview</a>), so a load balancer reaches gRPC and other routes on one port through an <code>HTTP2</code> backend for a TLS port, or an <code>H2C</code> backend for a plaintext one. H2C is also available to load balancers created by the GKE Gateway controller (<a href="https://docs.cloud.google.com/load-balancing/docs/https" target="_blank" rel="noreferrer">External Application Load Balancer overview</a>). The rule to &quot;use only gRPC or TCP health checks&quot; applies to backend services whose protocol is gRPC, not to an <code>HTTP2</code> or <code>H2C</code> backend (<a href="https://docs.cloud.google.com/load-balancing/docs/health-check-concepts" target="_blank" rel="noreferrer">Health checks overview</a>). A gRPC health check passes only on status <code>OK</code> with <code>SERVING</code>, and comes in <code>grpc</code> and <code>grpc_with_tls</code> forms.</p><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>Network reach and identity are separate settings. On Cloud Run, &quot;IAM authentication still applies to requests reaching the service ... from any of the preceding network ingress paths&quot; (<a href="https://docs.cloud.google.com/run/docs/securing/ingress" target="_blank" rel="noreferrer">Restrict network ingress for Cloud Run</a>), and public access means granting <code>allUsers</code> the <code>roles/run.invoker</code> role.</p><p>Staff tools sit behind Identity-Aware Proxy, which &quot;lets you establish a central authorization layer for applications accessed by HTTPS, so you can use an application-level access control model instead of relying on network-level firewalls&quot; (<a href="https://docs.cloud.google.com/iap/docs/concepts-overview" target="_blank" rel="noreferrer">Identity-Aware Proxy overview</a>).</p><h2 id="health-checks" tabindex="-1">Health checks <a class="header-anchor" href="#health-checks" aria-label="Permalink to &quot;Health checks&quot;">​</a></h2><p>GKE Ingress builds its load balancer health check outside the cluster. A <code>BackendConfig</code> on the Service takes precedence; without one, the GKE Ingress controller infers what it can, such as path, port and protocol, from the serving Pods&#39; <code>readinessProbe</code>, and uses defaults for the rest (<a href="https://docs.cloud.google.com/kubernetes-engine/docs/troubleshooting/ingress-health-checks" target="_blank" rel="noreferrer">Troubleshooting Ingress health checks</a>). It reads the probe only when its port &quot;must match the actual port your application is listening on within the container&quot;, that <code>containerPort</code> &quot;must match the Service&#39;s <code>targetPort</code>&quot;, and the Ingress backend references that Service port. A readiness probe on another port, such as <code>private</code> while the Ingress routes to <code>public</code>, leaves the default <code>/</code> check in place, so the health check has to come from a <code>BackendConfig</code> with <code>healthCheck.requestPath</code> and <code>healthCheck.port</code>. GKE Gateway does not: it requests <code>/</code> unless a <code>HealthCheckPolicy</code> says otherwise (<a href="https://docs.cloud.google.com/kubernetes-engine/docs/how-to/configure-gateway-resources" target="_blank" rel="noreferrer">Configure Gateway resources</a>).</p><p>Health check source ranges depend on the load balancer and backend type. For an external Application Load Balancer with instance group or zonal NEG backends, probes come from <code>35.191.0.0/16</code> (<code>2600:2d00:1:b029::/64</code> for IPv6) and proxied traffic also from <code>130.211.0.0/22</code>; regional and cross-region load balancers send traffic from their proxy-only subnet instead of <code>130.211.0.0/22</code> (<a href="https://docs.cloud.google.com/load-balancing/docs/firewall-rules" target="_blank" rel="noreferrer">Firewall rules for health checks</a>). For backend services that use gRPC, Google says to &quot;use only gRPC or TCP health checks. Don&#39;t use HTTP(S) or HTTP/2 health checks&quot; (<a href="https://docs.cloud.google.com/load-balancing/docs/health-check-concepts" target="_blank" rel="noreferrer">Health checks overview</a>).</p><p>Cloud Run supports startup probes over HTTP, TCP and gRPC, and liveness probes over HTTP and gRPC (<a href="https://docs.cloud.google.com/run/docs/configuring/healthchecks" target="_blank" rel="noreferrer">Configure container health checks</a>). It reserves paths starting with <code>/_ah/</code> and &quot;some paths ending with <code>z</code>&quot;, and recommends &quot;avoiding all paths that end in z&quot; (<a href="https://docs.cloud.google.com/run/docs/issues" target="_blank" rel="noreferrer">Cloud Run known issues</a>).</p>`,21)])])}const u=o(r,[["render",n]]);export{g as __pageData,u as default};
